 /* ---------- Notifications ---------- */
 const nt={scope:'mine',show:'open'};
 function notifications(root){
  const s=noticeState(),list=alerts(nt.scope).filter(a=>nt.show==='all'||!s.dismissed?.[a.key]);
  const sevTone={overdue:'crit',due:'warn',renewal:'info',info:''},sevName={overdue:t('متأخر','Overdue'),due:t('يستحق قريباً','Due soon'),renewal:t('تجديد','Renewal'),info:t('للعلم','For review')};
  root.innerHTML=`<div class="pagehead"><div><h1>${t('الإشعارات','Notifications')}</h1><p>${t('تنبيهات المواعيد والتجديدات والطلبات غير المعيّنة. تُحسب من سجلات البوابة مباشرة.','Deadlines, renewals and unassigned work, calculated directly from portal records.')}</p></div><div class="actions"><button class="btn ghost" type="button" id="readAll">${t('تعليم الكل كمقروء','Mark all as read')}</button></div></div>
   <section class="panel"><div class="toolbar"><div class="chips">${M.isAdmin()?`<button class="chip" type="button" data-scope="mine" aria-pressed="${nt.scope==='mine'}">${t('الخاصة بي','Mine')}</button><button class="chip" type="button" data-scope="team" aria-pressed="${nt.scope==='team'}">${t('كل الفريق','Whole team')}</button>`:''}<button class="chip" type="button" data-show="open" aria-pressed="${nt.show==='open'}">${t('الحالية','Current')}</button><button class="chip" type="button" data-show="all" aria-pressed="${nt.show==='all'}">${t('بما فيها المخفية','Include dismissed')}</button></div></div>
   ${list.length?`<div class="list">${list.map(a=>{const unread=!s.read?.[a.key]&&!s.dismissed?.[a.key];return `<div class="li"><span class="avatar" style="background:var(--${a.sev==='overdue'?'crit':a.sev==='due'?'warn':'accent'}-soft);color:var(--${a.sev==='overdue'?'crit':a.sev==='due'?'warn':'accent'})">${unread?'●':'○'}</span><a class="grow" href="${esc(a.url)}" data-read="${esc(a.key)}" style="text-decoration:none;color:inherit"><b style="${unread?'':'font-weight:400'}">${esc(a.title)}</b><small>${esc(L(a.kind))} · ${esc(a.detail)}${a.owner&&nt.scope==='team'?' · '+esc(person(a.owner)):''}</small></a>${pill(sevName[a.sev],sevTone[a.sev])}${s.dismissed?.[a.key]?'':`<button class="linkbtn" type="button" data-dismiss="${esc(a.key)}">${t('إخفاء','Dismiss')}</button>`}</div>`}).join('')}</div>`:`<p class="empty">${t('لا توجد تنبيهات.','You are all caught up.')}</p>`}</section>`;
  root.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{nt.scope=b.dataset.scope;notifications(root)});
  root.querySelectorAll('[data-show]').forEach(b=>b.onclick=()=>{nt.show=b.dataset.show;notifications(root)});
  root.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=async()=>{await markNotice([b.dataset.dismiss],'dismissed')});
  root.querySelectorAll('[data-read]').forEach(a=>a.addEventListener('click',()=>{markNotice([a.dataset.read],'read').catch(()=>{})}));
  root.querySelector('#readAll').onclick=async()=>{await markNotice(list.map(a=>a.key),'read');P.toast(t('تم','Done'))};
 }

